import * as THREE from 'three';

// 1. Create a container (Scene)
const scene = new THREE.Scene();

// 2. Create a Perspective Camera
const camera = new THREE.PerspectiveCamera(75, w/h, 0.1, 1000);

// 3. Create & size the Renderer
const renderer = new THREE.WebGLRenderer();
renderer.setSize(w, h);

// 4. Geometry + Material = Mesh
const mesh = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({ color: 0x3b82f6 })
);
scene.add(mesh);

// 5. The Render Loop (60fps)
function animate() {
  requestAnimationFrame(animate);
  mesh.rotation.y += 0.005; // Slow & smooth rotation
  renderer.render(scene, camera);
}
animate();

import React, { useRef, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';

function Box({ position, color }) {
  const mesh = useRef();
  const [active, setActive] = useState(false);

  // Rotation logic inside the loop
  useFrame(() => (mesh.current.rotation.x = mesh.current.rotation.y += 0.0025));

  return (
    <mesh
      position={position}
      ref={mesh}
      scale={active ? 1.5 : 1}
      onClick={() => setActive(!active)}
    >
      <boxGeometry args={[1, 1, 1]} />
      <meshStandardMaterial color={color} />
    </mesh>
  );
}

export default function App() {
  const [count, setCount] = useState(1);

  return (
    <div className="flex flex-col gap-4">
      <button onClick={() => setCount(c => c + 1)}>Add Box (State Update)</button>

      <Canvas>
        <OrbitControls />
        <ambientLight />
        <pointLight position={[10, 10, 10]} />

        {[...Array(count)].map((_, i) => (
          <Box key={i} position={[i * 1.5 - 1.5, i * 0.5, 0]} color="hotpink" />
        ))}
      </Canvas>
    </div>
  );
}

