import { Canvas } from '@react-three/fiber';
import { OrbitControls, Environment, useGLTF, useTexture } from '@react-three/drei';

function CustomModel({ texturePath }) {
  // 1. Load the custom 3D model (GLTF/GLB)
  const { scene } = useGLTF('/beer2.gltf');

  // 2. Load the dynamic texture
  const texture = useTexture(texturePath || '/Regular - texture.jpg');

  // 3. Apply texture to proper material (simple traversal)
  scene.traverse((child) => {
    if (child.isMesh && child.name === 'Can') {
      child.material.map = texture;
    }
  });

  return <primitive object={scene} />;
}

export default function FinalScene() {
  return (
    <Canvas>
      <OrbitControls autoRotate />
      <Environment preset="city" />
      <CustomModel />
    </Canvas>
  );
}
